@Override
public HashMap<Entity, Integer> getHits() {
    return this.hitsHashmap;
}

@Override
public void addToHits(Entity entity, int value) {
    this.hitsHashmap.put(entity, hitsHashmap.containsKey(entity) ? hitsHashmap.get(entity) + value: value);
}

@Override
public void setHits(Entity entity, int value) {
    this.hitsHashmap.put(entity, value);
}

public static void action(SerializableData.Instance data, Pair<Entity, Entity> pair) {
    if (pair.getRight().world.isClient || !(pair.getLeft() instanceof LivingEntity) || !(pair.getRight() instanceof LivingEntity) || ((LivingEntity) pair.getRight()).isDead()) return;
    int change = data.getInt("change");
    ResourceOperation operation = data.get("operation");
    switch (operation) {
        case ADD: {
            ((LivingEntityAccess)pair.getRight()).addToHits(pair.getLeft(), change);
            HitsOnTargetUtil.sendPacket((LivingEntity)pair.getRight(), (LivingEntity)pair.getLeft(), HitsOnTargetUtil.PacketType.SET, ((LivingEntityAccess)pair.getRight()).getHits().get(pair.getLeft()));
        }
        case SET: {
            ((LivingEntityAccess)pair.getRight()).setHits(pair.getLeft(), change);
            HitsOnTargetUtil.sendPacket((LivingEntity)pair.getRight(), (LivingEntity)pair.getLeft(), HitsOnTargetUtil.PacketType.REMOVE, 0);
        }
    }
}

public static ActionFactory<Pair<Entity, Entity>> getFactory() {
    return new ActionFactory<>(Apugli.identifier("change_hits_on_target"), new SerializableData()
            .add("change", SerializableDataTypes.INT)
            .add("operation", ApoliDataTypes.RESOURCE_OPERATION, ResourceOperation.ADD),
            ChangeHitsOnTargetAction::action
    );
}

public static void sendPacket(LivingEntity target, LivingEntity attacker, HitsOnTargetUtil.PacketType type, int setAmount) {
    PacketByteBuf buf = new PacketByteBuf(Unpooled.buffer());
    buf.writeInt(target.getId());
    buf.writeInt(attacker.getId());
    buf.writeByte(type.ordinal());
    if (type == PacketType.SET) {
        buf.writeInt(setAmount);
    }

    for (ServerPlayerEntity player : PlayerLookup.tracking(target)) {
        ServerPlayNetworking.send(player, ApugliPackets.SYNC_HITS_ON_TARGET, buf);
    }
    if (!(target instanceof ServerPlayerEntity)) return;
    ServerPlayNetworking.send((ServerPlayerEntity)target, ApugliPackets.SYNC_HITS_ON_TARGET, buf);
}

private static void onHitsOnTargetSync(MinecraftClient minecraftClient, ClientPlayNetworkHandler clientPlayNetworkHandler, PacketByteBuf packetByteBuf, PacketSender packetSender) {
    int targetId = packetByteBuf.readInt();
    int attackerId = packetByteBuf.readInt();
    HitsOnTargetUtil.PacketType type = HitsOnTargetUtil.PacketType.values()[packetByteBuf.readByte()];
    int amount = 0;
    if (type == HitsOnTargetUtil.PacketType.SET) {
        amount = packetByteBuf.readInt();
    }
    int finalAmount = amount;

    minecraftClient.execute(() -> {
        Entity target = clientPlayNetworkHandler.getWorld().getEntityById(targetId);
        Entity attacker = clientPlayNetworkHandler.getWorld().getEntityById(attackerId);
        if (!(target instanceof LivingEntity)) {
            Apugli.LOGGER.warn("Received unknown target");
        } else if (!(attacker instanceof LivingEntity)) {
            Apugli.LOGGER.warn("Received unknown attacker");
        } else switch (type) {
            case SET -> ((LivingEntityAccess)target).getHits().put(attacker, finalAmount);
            case REMOVE -> {
                if (!((LivingEntityAccess)target).getHits().containsKey(attacker)) return;
                ((LivingEntityAccess)target).getHits().remove(attacker);
            }
        }
    });
}

@Environment(EnvType.CLIENT)
public static void register() {
    ClientPlayConnectionEvents.INIT.register(((clientPlayNetworkHandler, minecraftClient) -> {
        ClientPlayNetworking.registerReceiver(ApugliPackets.REMOVE_STACK_FOOD_COMPONENT, ApugliPacketsS2C::onFoodComponentSync);
        ClientPlayNetworking.registerReceiver(ApugliPackets.SYNC_HITS_ON_TARGET, ApugliPacketsS2C::onHitsOnTargetSync);
    }));
}

public static boolean condition(SerializableData.Instance data, Pair<Entity, Entity> pair) {
    if (!(pair.getRight() instanceof LivingEntity)) return false;
    int hitsOnTarget = ((LivingEntity) pair.getRight()).isDead() ? 0 : ((LivingEntityAccess) pair.getRight()).getHits().getOrDefault(pair.getLeft(), 0);
    Comparison comparison = (Comparison)data.get("comparison");
    int compareTo = data.getInt("compare_to");
    return comparison.compare(hitsOnTarget, compareTo);
}

public static ConditionFactory<Pair<Entity, Entity>> getFactory() {
    return new ConditionFactory<>(Apugli.identifier("hits_on_target"), new SerializableData()
            .add("comparison", ApoliDataTypes.COMPARISON)
            .add("compare_to", SerializableDataTypes.INT),
            HitsOnTargetCondition::condition
    );
}

public static void register() {
    register(ChangeHitsOnTargetAction.getFactory());
}

public static void register() {
    register(HitsOnTargetCondition.getFactory());
}

