@Inject(method = "tickAngerLogic", at = @At(value = "INVOKE", target = "Lnet/minecraft/entity/mob/Angerable;getAngryAt()Ljava/util/UUID;"), locals = LocalCapture.CAPTURE_FAILHARD)
private void stopAngerOnTargets(ServerWorld world, boolean angerPersistent, CallbackInfo ci, LivingEntity livingEntity) {
    List<ModifyMobBehaviorPower> modifyMobBehaviorPowers = PowerHolderComponent.getPowers(livingEntity, ModifyMobBehaviorPower.class);
    boolean shouldMakePassive = modifyMobBehaviorPowers.stream().anyMatch(power -> power.doesApply(livingEntity, (MobEntity)this) && power.getMobBehavior().isPassive((MobEntity)(Object)this, livingEntity));

    if (shouldMakePassive) {
        this.stopAnger();
    }
}

public boolean doesApply(LivingEntity powerHolder, LivingEntity mob) {
    return this.bientityCondition == null || this.bientityCondition.test(new Pair<>(powerHolder, mob));
}

public MobBehavior getMobBehavior() {
    return mobBehavior;
}

@Override
public void tick() {
    if (entity.age % 10 != 0) return;

    ((ServerWorldAccessor)entity.world).getEntityManager().getLookup().forEach(TypeFilter.instanceOf(MobEntity.class), mob -> {
        if (this.doesApply(entity, mob)) {
            modifiableEntities.add(mob);
        }
    });

    modifiableEntities.removeIf(entity -> entity.isDead() || entity.isRemoved());

    if (this.isActive()) {
        for (Iterator<MobEntity> iterator = modifiableEntities.stream().filter(mob -> this.doesApply(entity, mob) && !mobBehavior.hasAppliedGoals(mob)).iterator(); iterator.hasNext();) {
            MobEntity mob = iterator.next();
            mobBehavior.initGoals(mob);
            this.modifiedEntities.add(mob);
        }
    }

    for (Iterator<MobEntity> iterator = modifiedEntities.stream().filter(mob -> !this.doesApply(entity, mob) || !this.isActive()).iterator(); iterator.hasNext();) {
        MobEntity mob = iterator.next();
        if (this.getMobBehavior().isHostile(mob, entity) && (mob.getTarget() == this.entity || mob instanceof Angerable && ((Angerable) mob).getAngryAt() == entity.getUuid())) {
            if (mob instanceof Angerable && ((Angerable) mob).getTarget() == entity) {
                ((Angerable) mob).stopAnger();
            }
            mob.setTarget(null);
        }
        this.mobBehavior.removeGoals(mob);
    }
    modifiedEntities.removeIf(mob -> !mobBehavior.hasAppliedGoals(mob) && (!this.doesApply(entity, mob) || !this.isActive()));
}

@Override
public void onRemoved() {
    if (entity.world.isClient) return;
    for (Iterator<MobEntity> iterator = modifiedEntities.stream().iterator(); iterator.hasNext();) {
        MobEntity mob = iterator.next();
        if (mob.getTarget() == this.entity || mob instanceof Angerable && ((Angerable) mob).getAngryAt() == entity.getUuid()) {
            if (mob instanceof Angerable && ((Angerable) mob).getTarget() == entity) {
                ((Angerable) mob).stopAnger();
            }
            mob.setTarget(null);
        }
        this.mobBehavior.removeGoals(mob);
    }
}

public boolean isPassive(MobEntity mob, LivingEntity target) {
    return false;
}

public void removeGoals(MobEntity mob) {
    ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().stream().filter(pair -> pair.getLeft() == this).forEach(pair -> ((MobEntityAccessor)mob).getTargetSelector().remove(pair.getRight()));
    ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().removeIf(pair -> pair.getLeft() == this);
    ((MobEntityAccess)mob).getModifiedGoalSelectorGoals().stream().filter(pair -> pair.getLeft() == this).forEach(pair -> ((MobEntityAccessor)mob).getGoalSelector().remove(pair.getRight()));
    ((MobEntityAccess)mob).getModifiedGoalSelectorGoals().removeIf(pair -> pair.getLeft() == this);
}

public boolean hasAppliedGoals(MobEntity mob) {
    return ((MobEntityAccess)mob).getModifiedTargetSelectorGoals().stream().filter(pair -> pair.getLeft() == this).toList().size() > 0 || ((MobEntityAccess)mob).getModifiedGoalSelectorGoals().stream().filter(pair -> pair.getLeft() == this).toList().size() > 0;
}
